/// <summary>
/// NDX_MultipleS_Sales_Item
/// </summary>
internal final class NDX_MultipleS_Sales_Item extends NDX_MultipleSelect_Sales
{
    InventTable inventTable;

}

Method.Source:
protected void new(InventTable _inventTable, SalesTable _salesTable = null)
{
    NDXMultipleS_Sales   nDX_MultipleS_Sales;
    ;
    super();

    inventTable  = _inventTable;

    if(_salesTable)
    {
        salesTable = _salesTable;
        salesId = salesTable.SalesId;
    }

    itemValidityErrors.ValidityCheckType = NDXValidityCheckType::SalesNumber;
    itemValidityErrors.checkMessage      = strfmt("@NDX:NDXItemValiditySalesTest", salesId);

    while select  nDX_MultipleS_Sales
        where nDX_MultipleS_Sales.RefRecId_InventTable == inventTable.RecId
    {
        nDX_SelectionTmp.RefRecId_SalesTable = nDX_MultipleS_Sales.RefRecId_SalesTable;
        nDX_SelectionTmp.insert();
    }
}

static public NDX_MultipleS_Sales_Item construct(InventTable _inventTable, SalesTable _salesTable = null)
{
    return new NDX_MultipleS_Sales_Item(_inventTable, _salesTable);
}

/// <summary>
/// Constructor
/// </summary>
/// <param name = "obj">NDX_ItemValidity</param>
/// <param name = "_salesTable">SalesTable</param>
/// <returns>NDX_MultipleS_Sales_Item object</returns>
static NDX_MultipleS_Sales_Item new_FromNDX_ItemValidity(NDX_ItemValidity obj, SalesTable _salesTable)
{
    NDX_MultipleS_Sales_Item      nDX_MultipleS_Sales_Item;
    ;
    nDX_MultipleS_Sales_Item = new NDX_MultipleS_Sales_Item(obj.parmInventTable(), _salesTable);
    nDX_MultipleS_Sales_Item.parmOItemValidity(obj);
    return nDX_MultipleS_Sales_Item;
}

/// <summary>
/// Chacks if item is valid for a sale
/// </summary>
/// <returns>container</returns>
public container isValid()
{
    NDXValidityMessage validityMessage = '';
    boolean     lIsValid = true;
    ;

    // keine Gültigkeitsprüfung hinterlegt
    if (nDX_SelectionTmp.RecId == 0)
    {
        return [lIsValid, validityMessage];
    }

    select firstonly nDX_SelectionTmp where nDX_SelectionTmp.RefRecId_SalesTable == salesTable.RecId;

    if (nDX_SelectionTmp)
    {
        return [lIsValid, validityMessage];
    }

    lIsValid        = false;

    // Der Artikel darf nur in den Aufträgen [%1] genutzt werden!

    validityMessage = strFmtLB(strfmt("@NDX:NDXItemValiditySales", NDXMultipleS_Sales::Range2String(InventTable.RecId)));

    itemValidityErrors.ErrorMessage = validityMessage;
    oItemValidity.addErrorMessage(itemValidityErrors);

    return [lIsValid, validityMessage];
}
